    urlComp.lpszHostName = hostName;
    urlComp.dwHostNameLength = (sizeof(hostName)/sizeof(wchar_t)) - 1;
    urlComp.lpszUrlPath = urlPath;
    urlComp.dwUrlPathLength = (sizeof(urlPath)/sizeof(wchar_t)) - 1;
