    HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", urlPath, nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, requestFlags);
    if (!hRequest) { error = L"WinHttpOpenRequest failed: " + toWide(lastError()); WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession); return false; }
    if (!WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0)) {
        error = L"WinHttpSendRequest failed: " + toWide(lastError());
        WinHttpCloseHandle(hRequest); WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession); return false;
    }
    if (!WinHttpReceiveResponse(hRequest, nullptr)) { ... }
    HANDLE hFile = CreateFileW(filePath.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (hFile == INVALID_HANDLE_VALUE) { error = L"CreateFile failed: " + toWide(lastError()); close handles; return false; }
    std::vector<char> buffer(65536);
    DWORD available = 0;
    bool ok = true;
    while (WinHttpQueryDataAvailable(hRequest, &available)) {
        if (available == 0) break;
        DWORD bytesRead = 0;
        if (!WinHttpReadData(hRequest, buffer.data(), available, &bytesRead) || bytesRead == 0) { ok=false; break; }
        DWORD bytesWritten = 0;
        if (!WriteFile(hFile, buffer.data(), bytesRead, &bytesWritten, nullptr) || bytesWritten != bytesRead) { ok=false; break; }
    }
    if (!ok) error = L"Download failed: " + toWide(lastError());
    CloseHandle(hFile);
    WinHttpCloseHandle(hRequest); WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession);
    return ok;
}

bool ExecuteFile(const std::wstring& filePath, std::wstring& error) {
    std::vector<wchar_t> cmdLine;
    cmdLine.reserve(filePath.size() + 3);
    cmdLine.push_back(L'"');
    for (wchar_t c : filePath) cmdLine.push_back(c);
    cmdLine.push_back(L'"');
    cmdLine.push_back(L'\0');
    STARTUPINFOW si; PROCESS_INFORMATION pi;
    ZeroMemory(&si, sizeof(si)); si.cb = sizeof(si);
    ZeroMemory(&pi, sizeof(pi));
    BOOL ok = CreateProcessW(nullptr, cmdLine.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi);
    if (!ok) { error = L"CreateProcess failed: " + toWide(lastError()); return false; }
    WaitForSingleObject(pi.hProcess, INFINITE);
    DWORD exitCode = 0;
    GetExitCodeProcess(pi.hProcess, &exitCode);
    CloseHandle(pi.hProcess); CloseHandle(pi.hThread);
    return true;
}

int main(int argc, char* argv[]) {
    if (argc < 2) { std::cerr << "Usage: " << argv[0] << " <URL-to-EXE>\n"; return 1; }
